    // Utilisation reward: highly utilised bins are better
    let util = 1.0 - residual_ratio;
    let util_reward = util.powi(3) * 12.0;
    score -= util_reward;

    // Tightness reward based on the square of the tightness
    let tightness = (1.0 - residual_ratio).powi(2) * 10.0;
